# filename: parse_houses.py

def extract_house_positions(path):
    with open(path, 'r') as f:
        lines = [line.rstrip('\n') for line in f]

    road_idx = None
    for i, line in enumerate(lines):
        # Heuristic: consider the line with the most '-' as the road
        if '-' in line:
            if road_idx is None or line.count('-') > lines[road_idx].count('-'):
                road_idx = i
    if road_idx is None:
        raise ValueError('Road line not found')

    house_positions = set()
    # Scan the line above and below the road for houses aligned to mile markers
    for offset in (-1, 1):
        r = road_idx + offset
        if 0 <= r < len(lines):
            for c, ch in enumerate(lines[r]):
                if ch == 'H':
                    house_positions.add(c)

    return sorted(house_positions)

